('shop-2', 'Apex Tech & Gadget Hub', 'Electronics', 'Vidyanagar', 'Opp. KLE Tech University, Vidyanagar, Hubballi - 580021', 'Trusted neighbourhood electronics store offering warranty-backed tech accessories, audio gear, cables, and smart home essentials.', 4.7, 98, 'https://images.unsplash.com/photo-1550009158-9ebf69173e03?auto=format&fit=crop&w=600&q=80', '+91 98802 33411', '10:00 AM - 9:30 PM', 'active'),
('shop-3', 'Vogue Craft & Handloom Studio', 'Fashion', 'Koppikar Road', 'Near Cotton Market, Koppikar Road, Hubballi - 580020', 'Boutique studio celebrating Karnataka and South Indian handloom weaves, pure cotton everyday wear, and eco-conscious canvas totes.', 4.9, 76, 'https://images.unsplash.com/photo-1489987707025-afc232f7ea0f?auto=format&fit=crop&w=600&q=80', '+91 97412 88902', '10:30 AM - 8:30 PM', 'active'),
('shop-4', 'Saraswati Book Haven & Fine Papers', 'Books & Stationery', 'Keshwapur', 'Kusugal Road, Keshwapur, Hubballi - 580023', 'Iconic independent bookstore carrying Indian literature, academic titles, vintage fountain pen inks, and handmade cotton journals.', 4.9, 210, 'https://images.unsplash.com/photo-1507842229450-79779f62a6b2?auto=format&fit=crop&w=600&q=80', '+91 98440 11988', '9:30 AM - 8:30 PM', 'active'),
('shop-5', 'Prakriti Home & Sustainable Living', 'Home & Living', 'Shirur Park', 'Shirur Park 2nd Cross, Vidyanagar, Hubballi - 580021', 'Conscious home lifestyle store curating artisanal terracotta planters, brass decor, soy wax aromatherapy candles, and handwoven mats.', 4.6, 65, 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=600&q=80', '+91 99003 44521', '10:00 AM - 8:00 PM', 'active'),
('shop-6', 'Veda Botanics & Apothecary', 'Personal Care', 'Gokul Road', 'Near Airport Bypass, Gokul Road, Hubballi - 580030', 'Clean personal care apothecary formulating small-batch herbal soaps, pure floral hydrosols, and therapeutic scalp elixirs.', 4.8, 114, 'https://images.unsplash.com/photo-1608248597359-54848378216c?auto=format&fit=crop&w=600&q=80', '+91 96118 77203', '10:00 AM - 9:00 PM', 'active'),
('shop-7', 'DecaPulse Sports & Outdoor Hub', 'Sports & Lifestyle', 'Unkal', 'Unkal Lake Promenade, PB Road, Hubballi - 580031', 'Neighbourhood destination for high-grade badminton rackets, eco-friendly cork yoga mats, cycling gear, and endurance fitness accessories.', 4.8, 89, 'https://images.unsplash.com/photo-1517649763962-0c623266ddc0?auto=format&fit=crop&w=600&q=80', '+91 98860 45678', '9:00 AM - 9:30 PM', 'active')
